import{_ as l,c as n,o as e,ah as a}from"./chunks/framework.DE7iKuik.js";const h=JSON.parse('{"title":"事件和自定义脚本","frontmatter":{"title":"事件和自定义脚本","createTime":"2025/01/17 19:27:31","permalink":"/docs/composer/scripts.html","lastUpdated":"2026-01-20","tags":[],"link":"/docs/composer/官方文章/scripts","layout":"doc","sidebar":true,"aside":true,"prev":{"text":"创建 Composer 插件","link":"/docs/composer/官方文章/plugins"},"next":{"text":"故障排除","link":"/docs/composer/官方文章/troubleshooting"}},"headers":[],"params":{"pkg":"composer/官方文章/scripts","sidebar":[{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"为什么 Composer 不递归加载代码库？","dir":"常见问题","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively","children":[null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"可执行二进制文件","dir":"官方文章","link":"/docs/composer/官方文章/binaries","children":[null,null,null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]},{"text":"社区","dir":"教程","link":"/docs/composer/教程/community","children":[null,null,null,null,null,null,null,null]}],"versions":[]},"relativePath":"docs/composer/官方文章/scripts.md","filePath":"docs/[pkg].md"}'),o={name:"docs/composer/官方文章/scripts.md"};function p(i,s,c,t,r,d){return e(),n("div",null,[...s[0]||(s[0]=[a(`<h1 id="执行命令" tabindex="-1">执行命令 <a class="header-anchor" href="#执行命令" aria-label="Permalink to “执行命令”">​</a></h1><h2 id="什么是-script" tabindex="-1">什么是 <code>script</code> ? <a class="header-anchor" href="#什么是-script" aria-label="Permalink to “什么是 script ?”">​</a></h2><p><code>script</code> 被定义在 <code>composer.json</code> 里，可以是 PHP 类静态方法，也可以是可执行的命令行调用。<code>script</code> 是用来 Composer 执行时执行扩展包里的自定义代码，或者扩展包专属的命令行。</p><blockquote><p>注：只有项目里的 <code>composer.json</code> 会被执行，很多时候我们的项目会依赖于多个扩展，这些扩展里的里 <code>composer.json</code> 配置的 <code>script</code> 将不会被执行。</p></blockquote><hr><blockquote><p>译者注：Laravel 中利用 Composer 的 Script 来执行安装完后的动作，请见代码 <a href="https://github.com/laravel/laravel/blob/master/composer.json#L40-L51" target="_blank" rel="noreferrer">https://github.com/laravel/laravel/blob/master/composer.json#L40-L51</a> 。 事件名称</p></blockquote><hr><p>Composer 在执行的过程中会触发这些事件，你可以通过监控这些事件来控制 <code>scirpt</code> 的执行顺序。</p><h3 id="命令事件" tabindex="-1">命令事件 <a class="header-anchor" href="#命令事件" aria-label="Permalink to “命令事件”">​</a></h3><ul><li>pre-install-cmd: 当项目里有 <code>composer.lock</code> 文件的情况下调用 <code>install</code> 命令执行前</li><li>post-install-cmd: 当项目里有 <code>composer.lock</code> 文件的情况下调用 <code>install</code> 命令执行后</li><li>pre-update-cmd: 当 <code>update</code> 命令被执行前，或者当项目里没有 <code>composer.lock</code> 文件的情况下调用 <code>install</code> 命令执行前</li><li>post-update-cmd: 当 <code>update</code> 命令被执行后，或者当项目里没有 <code>composer.lock</code> 文件的情况下调用 <code>install</code> 命令执行后</li><li>post-status-cmd: 当 <code>status</code> 命令被执行后</li><li>pre-archive-cmd: 当 <code>archive</code> 命令被执行前</li><li>post-archive-cmd: 当 <code>archive</code> 命令被执行后</li><li>pre-autoload-dump: 当自动加载器 dump 成功了前触发，调用 <code>install</code>/<code>update</code> 或者 <code>dump-autoload</code> 命令时都会触发此事件</li><li>post-autoload-dump: 当自动加载器 dump 成功了后触发，调用 <code>install</code>/<code>update</code> 或者 <code>dump-autoload</code> 命令时都会触发此事件</li><li>post-root-package-install: 当执行 <code>create-project</code> 命令时，在根项目安装成功后</li><li>post-create-project-cmd: 当 <code>create-project</code>  命令被执行后</li></ul><h3 id="安装器事件" tabindex="-1">安装器事件 <a class="header-anchor" href="#安装器事件" aria-label="Permalink to “安装器事件”">​</a></h3><ul><li>pre-dependencies-solving: 当依赖被解析前</li><li>post-dependencies-solving: 当依赖被解析后</li></ul><h3 id="扩展包事件" tabindex="-1">扩展包事件 <a class="header-anchor" href="#扩展包事件" aria-label="Permalink to “扩展包事件”">​</a></h3><ul><li>pre-package-install: 当扩展包被安装前</li><li>post-package-install: 当扩展包被安装后</li><li>pre-package-update: 当扩展包被更新前</li><li>post-package-update: 当扩展包被更新后</li><li>pre-package-uninstall: 当扩展包被移除前</li><li>post-package-uninstall: 当扩展包被移除后</li></ul><h3 id="插件事件" tabindex="-1">插件事件 <a class="header-anchor" href="#插件事件" aria-label="Permalink to “插件事件”">​</a></h3><ul><li>init: 当 Composer 实例初始化成功后触发</li><li>command: 在命令行里执行任何 Composer 命令前都会调用，提供了一个可读取程序输入和输出对象的接口</li><li>pre-file-download: 在文件还未被下载前，允许你操作 <code>RemoteFilesystem</code> 文件下载对象</li><li>pre-command-run: 当命令一个命令被执行前，允许你对 <code>InputInterface</code> 对象进行操作，例如命令输入的 <code>options</code> 和 <code>arguments</code> ，以此来控制命令的行为</li></ul><blockquote><p>请注意：在 <code>install</code> 或者<code>update</code> 前，Composer 对你的依赖是一无所知的，所以你不应该在 <code>pre-update-cmd</code> 或者 <code>pre-install-cmd</code> 事件中使用任何第三方依赖的命令。如果你不得不这么做，你可以在你的项目里编写逻辑，然后在 <code>install</code> 或 <code>update</code> 命令触发时调用你自己的命令。</p></blockquote><h2 id="定义-scripts" tabindex="-1">定义 <code>scripts</code> <a class="header-anchor" href="#定义-scripts" aria-label="Permalink to “定义 scripts”">​</a></h2><p>我们需要在项目的 <code>composer.json</code> 定义一个叫 <code>&quot;scripts&quot;</code> 的选项，在此选项里，设置事件名称和对应的要执行的命令或脚本。命令和脚本的值可以是字符串的名称，也可以是数组（单个或者多个）。</p><p>对于每一个事件：</p><ul><li>Scripts 执行的顺序遵循事件触发的顺序；</li><li>事件对于的值为数组的，数组里的每个项可以是 PHP 脚本或者是命令行；</li><li>PHP 类定义的回调，必须由 Composer 的加载器价值；</li><li>回调可以是 psr-0, psr-4 或者 classmap 定义。如果你的脚本需要外部依赖，你需要自己加载这些类依赖。</li></ul><p>例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;scripts&quot;: {</span></span>
<span class="line"><span>        &quot;post-update-cmd&quot;: &quot;MyVendor\\\\MyClass::postUpdate&quot;,</span></span>
<span class="line"><span>        &quot;post-package-install&quot;: [</span></span>
<span class="line"><span>            &quot;MyVendor\\\\MyClass::postPackageInstall&quot;</span></span>
<span class="line"><span>        ],</span></span>
<span class="line"><span>        &quot;post-install-cmd&quot;: [</span></span>
<span class="line"><span>            &quot;MyVendor\\\\MyClass::warmCache&quot;,</span></span>
<span class="line"><span>            &quot;phpunit -c app/&quot;</span></span>
<span class="line"><span>        ],</span></span>
<span class="line"><span>        &quot;post-autoload-dump&quot;: [</span></span>
<span class="line"><span>            &quot;MyVendor\\\\MyClass::postAutoloadDump&quot;</span></span>
<span class="line"><span>        ],</span></span>
<span class="line"><span>        &quot;post-create-project-cmd&quot;: [</span></span>
<span class="line"><span>            &quot;php -r \\&quot;copy(&#39;config/local-example.php&#39;, &#39;config/local.php&#39;);\\&quot;&quot;</span></span>
<span class="line"><span>        ]</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>照着上面的定义，我们来编写  <code>MyVendor\\MyClass</code> 类，此类的作用是来执行这些回调（注意都是静态方法）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;?php</span></span>
<span class="line"><span></span></span>
<span class="line"><span>namespace MyVendor;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>use Composer\\Script\\Event;</span></span>
<span class="line"><span>use Composer\\Installer\\PackageEvent;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>class MyClass</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    public static function postUpdate(Event $event)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        $composer = $event-&gt;getComposer();</span></span>
<span class="line"><span>        // do stuff</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    public static function postAutoloadDump(Event $event)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        $vendorDir = $event-&gt;getComposer()-&gt;getConfig()-&gt;get(&#39;vendor-dir&#39;);</span></span>
<span class="line"><span>        require $vendorDir . &#39;/autoload.php&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        some_function_from_an_autoloaded_file();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    public static function postPackageInstall(PackageEvent $event)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        $installedPackage = $event-&gt;getOperation()-&gt;getPackage();</span></span>
<span class="line"><span>        // do stuff</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    public static function warmCache(Event $event)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        // make cache toasty</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>请注意：在 Composer 的 <code>install</code> 和 <code>update</code> 过程时，环境变量 <code>COMPOSER_DEV_MODE</code> 会被设置，此值来自于执行命令时的 <code>--no-dev</code> 参数，如果设置了为 0，每调用的情况下为 1。</p><h2 id="事件类" tabindex="-1">事件类 <a class="header-anchor" href="#事件类" aria-label="Permalink to “事件类”">​</a></h2><p>当事件被触发时，PHP 的回调代码中会接收到 <code>Composer\\EventDispatcher\\Event</code> 对象。此对象会有一个 <code>getName()</code> 方法来让你获取到事件的名称。</p><p>取决于 <a href="https://github.com/composer/composer/blob/master/doc/articles/scripts.md#event-names" target="_blank" rel="noreferrer">script 类型</a> 你会获取到不同的类对象以及各类型对象包含的变量：</p><ul><li>基类：<a href="https://getcomposer.org/apidoc/master/Composer/EventDispatcher/Event.html" target="_blank" rel="noreferrer"><code>Composer\\EventDispatcher\\Event</code></a></li><li>事件类： <a href="https://getcomposer.org/apidoc/master/Composer/Script/Event.html" target="_blank" rel="noreferrer"><code>Composer\\Script\\Event</code></a></li><li>安装器事件: <a href="https://getcomposer.org/apidoc/master/Composer/Installer/InstallerEvent.html" target="_blank" rel="noreferrer"><code>Composer\\Installer\\InstallerEvent</code></a></li><li>扩展事件: <a href="https://getcomposer.org/apidoc/master/Composer/Installer/PackageEvent.html" target="_blank" rel="noreferrer"><code>Composer\\Installer\\PackageEvent</code></a></li><li>插件事件: <ul><li>init: <a href="https://getcomposer.org/apidoc/master/Composer/EventDispatcher/Event.html" target="_blank" rel="noreferrer"><code>Composer\\EventDispatcher\\Event</code></a></li><li>command: <a href="https://getcomposer.org/apidoc/master/Composer/Plugin/CommandEvent.html" target="_blank" rel="noreferrer"><code>Composer\\Plugin\\CommandEvent</code></a></li><li>pre-file-download: <a href="https://getcomposer.org/apidoc/master/Composer/Plugin/PreFileDownloadEvent.html" target="_blank" rel="noreferrer"><code>Composer\\Plugin\\PreFileDownloadEvent</code></a></li></ul></li></ul><h2 id="手动执行-scripts" tabindex="-1">手动执行 <code>scripts</code> <a class="header-anchor" href="#手动执行-scripts" aria-label="Permalink to “手动执行 scripts”">​</a></h2><p>如果你想要手动执行一个事件对应的 <code>scripts</code> ，语法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>composer run-script [--dev] [--no-dev] script</span></span></code></pre></div><p>例如 <code>composer run-script post-install-cmd</code> 会运行 <code>post-install-cmd</code> 对应的 <code>scripts</code>。</p><p>你可以使用 <code>--</code> 来给 <code>scripts</code> 传参，例如 <code>composer run-script post-install-cmd -- --check</code> ，<code>scripts</code> 是命令的情况下，会如正常传参那样接收到 <code>--check</code> 参数，而使用 PHP 脚本的情况下，你可以使用 <code>$event-&gt;getArguments()</code> 来获取到相同的传参。</p><h2 id="编写自定义命令" tabindex="-1">编写自定义命令 <a class="header-anchor" href="#编写自定义命令" aria-label="Permalink to “编写自定义命令”">​</a></h2><p>如果你的自定义 <code>scripts</code> 逻辑与所有事件名称都不匹配的话，你也可以自定义自己的 Composer 命令。如下面的定义允许你新增 <code>composer test</code> 命令:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;scripts&quot;: {</span></span>
<span class="line"><span>        &quot;test&quot;: &quot;phpunit&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这种模式与 <code>run-script</code> 命令一样可以接收参数，如： <code>composer test -- --filter &lt;pattern&gt;</code> 会将参数 <code>--filter &lt;pattern&gt;</code> 传到 <code>phpunit</code> 脚本中。</p><blockquote><p>注意：在执行脚本前，你需要知道，按照一般情况下的配置 Composer 的 <code>bin</code> 目录会放到系统 PATH 前面，所以以上命令 <code>phpunit</code> 无论是在 <code>vendor/bin/phpunit</code> 或者在 <code>bin/phpunit</code> 中，都能够被执行到。</p></blockquote><h2 id="引用脚本" tabindex="-1">引用脚本 <a class="header-anchor" href="#引用脚本" aria-label="Permalink to “引用脚本”">​</a></h2><p>为了重新使用脚本以及避免重复启用脚本，可以通过在命令前面加上一个  <code>@</code> 来调用另外一个脚本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;scripts&quot;: {</span></span>
<span class="line"><span>        &quot;test&quot;: [</span></span>
<span class="line"><span>            &quot;@clearCache&quot;,</span></span>
<span class="line"><span>            &quot;phpunit&quot;</span></span>
<span class="line"><span>        ],</span></span>
<span class="line"><span>        &quot;clearCache&quot;: &quot;rm -rf cache/*&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="调用-composer-命令" tabindex="-1">调用 Composer 命令 <a class="header-anchor" href="#调用-composer-命令" aria-label="Permalink to “调用 Composer 命令”">​</a></h2><p>要调用 Composer 命令，可以使用 <code>@composer</code>  ，它会自动解析到当前正在使用的 composer.phar 上面：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;scripts&quot;: {</span></span>
<span class="line"><span>        &quot;test&quot;: [</span></span>
<span class="line"><span>            &quot;@composer install&quot;,</span></span>
<span class="line"><span>            &quot;phpunit&quot;</span></span>
<span class="line"><span>        ]</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="这样做的一个限制是-你不能像-composer-install-composer-foo-这样在一行调用多个-composer-命令。你必须把他们分隔成一个-json-命令数组。执行-php-脚本" tabindex="-1">这样做的一个限制是，你不能像 <code>@composer install &amp;&amp; @composer foo</code> 这样在一行调用多个 composer 命令。你必须把他们分隔成一个 JSON 命令数组。 执行 PHP 脚本 <a class="header-anchor" href="#这样做的一个限制是-你不能像-composer-install-composer-foo-这样在一行调用多个-composer-命令。你必须把他们分隔成一个-json-命令数组。执行-php-脚本" aria-label="Permalink to “这样做的一个限制是，你不能像 @composer install &amp;&amp; @composer foo 这样在一行调用多个 composer 命令。你必须把他们分隔成一个 JSON 命令数组。执行 PHP 脚本”">​</a></h2><p>要执行 PHP 脚本，您可以使用 <code>@php</code> 它将自动解析为当前正在使用的 PHP 进程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;scripts&quot;: {</span></span>
<span class="line"><span>        &quot;test&quot;: [</span></span>
<span class="line"><span>            &quot;@php script.php&quot;,</span></span>
<span class="line"><span>            &quot;phpunit&quot;</span></span>
<span class="line"><span>        ]</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这样做的局限是您不能像  <code>@php install &amp;&amp; @php foo</code> 这样调用多个命令。您必须将它们拆分为 JSON 命令数组。</p><h2 id="自定义说明" tabindex="-1">自定义说明 <a class="header-anchor" href="#自定义说明" aria-label="Permalink to “自定义说明”">​</a></h2><p>您可以在 <code>composer.json</code> 文件中使用以下内容来设置自定义脚本描述：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>{</span></span>
<span class="line"><span>    &quot;scripts-descriptions&quot;: {</span></span>
<span class="line"><span>        &quot;test&quot;: &quot;Run all tests!&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><blockquote><p>注意：您只能设置自定义命令的自定义描述.</p></blockquote>`,54)])])}const m=l(o,[["render",p]]);export{h as __pageData,m as default};
